sys_variable_value.value:
(function execute(inputs, outputs) {
    var spend = parseFloat(inputs.spend_amt) || 0;
    var factor = parseFloat(inputs.factor) || 0.42; // Default spend factor (lbs CO2e per $)
    
    // Calculate total CO2e impact in lbs based on spend
    var totalCo2eLbs = spend * factor;
    
    outputs.total_co2e_lbs = totalCo2eLbs;
})(inputs, outputs);

